use crate::{gather_input::Recipe,editor::Action};
pub const ENTRIES:&[(&str,&Recipe)]=&[("Nurbs Surface Network",&crate::network_geometry::RECIPE),("Nurbs Surface 4 Points",&crate::patch_geometry::RECIPE),("Loft",&crate::loft_geometry::RECIPE),("Nurbs Surface Loft",&crate::nurbs_loft_geometry::RECIPE),("Nurbs Surface Sweep1",&crate::sweep1_geometry::RECIPE),("Nurbs Surface Sweep2",&crate::sweep2_geometry::RECIPE),("Extrude",&crate::extrude_geometry::RECIPE),("Nurbs Surface Revolve",&crate::revolve_geometry::RECIPE)];
pub fn command(name:&str,text:&str)->Option<Result<Action,String>>{let(_,recipe)=ENTRIES.iter().find(|(label,_)|*label==name)?;if name=="Nurbs Surface 4 Points"&&!text.trim().is_empty()&&text.split_whitespace().count()!=4{return Some(Err("Nurbs Surface 4 Points takes 4 corner points".into()))}Some(Ok(Action::GatherBegin{recipe,text:text.into()}))}
pub fn alias(line:&str)->String{let mut words=line.split_whitespace();if words.clone().take(3).collect::<Vec<_>>().join(" ").eq_ignore_ascii_case("Nurbs Nurbs Network"){return std::iter::once("Nurbs Surface Network").chain(words.skip(3)).collect::<Vec<_>>().join(" ")}let Some(first)=words.next()else{return line.into()};let name=match first.to_ascii_lowercase().as_str(){"nurbssurface_network"|"nurbsnurbs_network"=>"Nurbs Surface Network","nurbssurface_4_points"=>"Nurbs Surface 4 Points","nurbssurface_loft"=>"Nurbs Surface Loft","nurbssurface_sweep1"=>"Nurbs Surface Sweep1","nurbssurface_sweep2"=>"Nurbs Surface Sweep2","nurbssurface_revolve"=>"Nurbs Surface Revolve",_=>return line.into()};std::iter::once(name).chain(words).collect::<Vec<_>>().join(" ")}
